import './style.css';
import {createIcons,Archive,ArchiveRestore,ArrowDown,ArrowLeft,ArrowRight,ArrowUpRight,BookOpen,Camera,Check,ChevronLeft,ChevronRight,ContactRound,Download,Eye,Feather,File,FilePenLine,Folder,Folders,ImageOff,Inbox,Info,KeyRound,Languages,Layers2,ListFilter,LogOut,Mail,MailOpen,MailPlus,Mails,Menu,Paperclip,Pause,Pencil,Play,Plus,RefreshCw,Reply,Save,Search,SearchX,Send,Settings2,ShieldCheck,Sparkles,SquarePen,Star,Trash2,Undo2,Unplug,UserPlus,X} from 'lucide';
const icons={Archive,ArchiveRestore,ArrowDown,ArrowLeft,ArrowRight,ArrowUpRight,BookOpen,Camera,Check,ChevronLeft,ChevronRight,ContactRound,Download,Eye,Feather,File,FilePenLine,Folder,Folders,ImageOff,Inbox,Info,KeyRound,Languages,Layers2,ListFilter,LogOut,Mail,MailOpen,MailPlus,Mails,Menu,Paperclip,Pause,Pencil,Play,Plus,RefreshCw,Reply,Save,Search,SearchX,Send,Settings2,ShieldCheck,Sparkles,SquarePen,Star,Trash2,Undo2,Unplug,UserPlus,X};
import DOMPurify from 'dompurify';
import {db,api,login,register} from './cloud.js';
import {esc,initials,fmtDate,bytes,fuzzy,exportCSV,mboxEntry,countRows} from './core.js';
const $=(q,root=document)=>root.querySelector(q),$$=(q,root=document)=>[...root.querySelectorAll(q)];
const I=(name,size=19)=>`<i data-lucide="${name}" style="width:${size}px;height:${size}px" aria-hidden="true"></i>`;
const S={user:null,accounts:[],categories:[],contacts:[],drafts:[],settings:{},counts:[],view:'inbox',folder:'inbox',remoteFolder:'',account:'',category:'',sender:'',query:'',unread:false,starred:false,messages:[],total:0,page:0,selected:new Set(),current:null,compose:null,translation:'',language:'简体中文',mobileNav:false,busy:false,listRequest:0};
let interval,searchTimer,authMode='login',booting=true;
function iconsNow(){createIcons({icons});}
function toast(message,error=false){const n=document.createElement('div');n.className='toast'+(error?' error':'');n.textContent=message;$('#toasts').append(n);setTimeout(()=>n.remove(),error?11000:5500);}
function error(e){toast(e.message||String(e),true);}
function download(content,name,type='text/plain;charset=utf-8'){const blob=content instanceof Blob?content:new Blob([content],{type});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download=name;link.click();setTimeout(()=>URL.revokeObjectURL(link.href),5000);}
const from64=s=>Uint8Array.from(atob(s),c=>c.charCodeAt(0));
const to64=async file=>{const a=new Uint8Array(await file.arrayBuffer());let s='';for(let i=0;i<a.length;i+=16384)s+=String.fromCharCode(...a.subarray(i,i+16384));return btoa(s);};
const account=id=>S.accounts.find(x=>x.id===id),category=id=>S.categories.find(x=>x.id===id),contact=email=>S.contacts.find(x=>[x.email,x.second_email].includes(email));
const badge=a=>a?`<span class="account-badge" style="--tag:${esc(a.color)}"><span></span>${esc(a.label)}</span>`:'—';
function avatar(c,email='',large=false){return `<span class="avatar ${large?'large':''}">${c?.photo_url?`<img src="${esc(c.photo_url)}" alt="${esc(c.name||email)}">`:esc(initials(c?.name||email))}</span>`;}
const listViews=['inbox','sent','archive','trash','spam','custom','drafts'];
const folderLabels={inbox:'收件箱',sent:'已发送',drafts:'草稿箱',archive:'归档',trash:'垃圾箱',spam:'垃圾邮件',custom:'原邮箱文件夹'};
function photoStatus(c){return c.photo_path?(c.photo_source==='auto'?'官网匹配 · 已保存':'已上传照片'):({not_found:'没有足够匹配的照片 · 已记录',insufficient:'需要可核对的真实姓名与机构邮箱',unavailable:'公开来源暂不可用 · 可手动重试',manual_empty:'已手动留空'}[c.photo_lookup_status]||'仅保存明确匹配的照片');}
function navCount(predicate){return countRows(S.counts,predicate);}
async function bootstrap(){const data=await api('bootstrap');Object.assign(S,data);S.language=S.settings.translation_language||'简体中文';}
function closeModal(){$('#modal-root').innerHTML='';}
function modal(title,content,wide=false){$('#modal-root').innerHTML=`<div class="modal-shade"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-label="${esc(title)}"><header><h2>${esc(title)}</h2><button class="icon-btn" data-action="close-modal" aria-label="关闭">${I('x')}</button></header>${content}</section></div>`;iconsNow();setTimeout(()=>$('input:not([type=hidden]),textarea,select',$('#modal-root'))?.focus(),20);}
function loginView(){clearInterval(interval);$('#app').innerHTML=`<main class="auth-page"><section class="auth-story"><a class="brand" href="#">${I('mails',30)}<span>Mail Atlas<small>私人邮件工作台</small></span></a><div class="story-copy"><span class="eyebrow">A QUIETER WAY TO EMAIL</span><h1>所有来信，<br>井然有序。</h1><p>把不同邮箱里的声音，<br>收进同一个从容的工作空间。</p><div class="story-mail"><span class="story-dot"></span><div><strong>一个收件箱，连接每一种可能</strong><p>多邮箱 · 智能分类 · 跨语言沟通</p></div>${I('arrow-up-right',22)}</div></div><footer>MAIL ATLAS <span>YOUR MAIL. YOUR SPACE.</span></footer></section><section class="auth-form-wrap"><div class="auth-form"><span class="eyebrow">WELCOME TO YOUR INBOX</span><h2>${authMode==='login'?'欢迎回来':'建立你的邮件空间'}</h2><p class="muted">${authMode==='login'?'使用文献管理系统的账号，即可登录。':'账号与 Paper Atlas 文献管理系统共用。'}</p><div class="auth-tabs"><button data-action="auth-login" class="${authMode==='login'?'active':''}">登录</button><button data-action="auth-register" class="${authMode==='register'?'active':''}">注册账号</button></div><form id="auth-form">${authMode==='register'?'<label>用户名<input name="username" required pattern="[A-Za-z0-9_]{3,24}" autocomplete="username" placeholder="3–24位字母、数字或下划线"></label><label>邮箱<input name="email" type="email" required autocomplete="email" placeholder="你的邮箱地址"></label>':'<label>用户名或邮箱<input name="identifier" required autocomplete="username" placeholder="输入用户名或邮箱"></label>'}<label>密码<div class="password-input"><input name="password" type="password" required minlength="8" autocomplete="${authMode==='login'?'current-password':'new-password'}" placeholder="${authMode==='login'?'输入密码':'至少8位字符'}"><button type="button" class="icon-btn" data-action="toggle-password" aria-label="显示或隐藏密码">${I('eye')}</button></div></label><div class="auth-options"><label class="check"><input name="remember" type="checkbox" checked> 自动登录</label><button type="button" class="text-btn" data-action="forgot">忘记密码</button></div><button class="primary auth-submit" type="submit">${authMode==='login'?'进入收件箱':'注册并进入'} ${I('arrow-right',18)}</button><p class="form-error" role="alert"></p></form><p class="auth-note">${I('shield-check',15)} 私人云端存储 · 每个账号独立隔离</p></div></section></main>`;iconsNow();}
function sidebar(){const unread=navCount(x=>x.folder==='inbox'&&!x.is_read);const custom=S.accounts.flatMap(a=>(a.sync_state?.folders||[]).filter(f=>f.kind==='custom').map(f=>({...f,account:a})));return `<aside class="sidebar ${S.mobileNav?'open':''}"><a class="brand" href="#" data-action="home">${I('mails',28)}<span>Mail Atlas<small>邮件工作台</small></span></a><button class="primary compose-btn" data-action="compose">${I('square-pen')} 写邮件</button><nav aria-label="主导航"><button class="nav-item ${S.view==='inbox'&&!S.starred?'active':''}" data-action="nav" data-view="inbox">${I('inbox')}<span>收件箱</span>${unread?`<b>${unread}</b>`:''}</button><button class="nav-item ${S.view==='categories'?'active':''}" data-action="nav" data-view="categories">${I('folders')}<span>分类邮件</span></button><button class="nav-item ${S.view==='contacts'?'active':''}" data-action="nav" data-view="contacts">${I('contact-round')}<span>联系人</span></button><div class="nav-divider"></div><button class="nav-item ${S.starred?'active':''}" data-action="favorites">${I('star')}<span>星标邮件</span></button><button class="nav-item ${S.view==='sent'?'active':''}" data-action="nav" data-view="sent">${I('send')}<span>已发送</span></button><button class="nav-item ${S.view==='drafts'?'active':''}" data-action="nav" data-view="drafts">${I('file-pen-line')}<span>草稿箱</span><small>${S.drafts.length+navCount(x=>x.folder==='drafts')}</small></button><button class="nav-item ${S.view==='archive'?'active':''}" data-action="nav" data-view="archive">${I('archive')}<span>归档</span></button><button class="nav-item ${S.view==='trash'?'active':''}" data-action="nav" data-view="trash">${I('trash-2')}<span>垃圾箱</span></button><button class="nav-item ${S.view==='spam'?'active':''}" data-action="nav" data-view="spam">${I('mail')}<span>垃圾邮件</span></button></nav>${custom.length?`<div class="sidebar-section"><div class="section-label">原邮箱文件夹</div>${custom.map(f=>`<button class="mailbox-link ${S.remoteFolder===f.path&&S.account===f.account.id?'selected':''}" data-action="remote-folder" data-id="${f.account.id}" data-path="${esc(f.path)}">${I('folder',15)}<span>${esc(f.name)}<small>${esc(f.account.label)}</small></span></button>`).join('')}</div>`:''}<div class="sidebar-section"><div class="section-label">我的邮箱<button class="icon-btn small" data-action="add-account" aria-label="添加邮箱">${I('plus',15)}</button></div><button class="mailbox-link ${!S.account?'selected':''}" data-action="account" data-id=""><span class="all-dot">${I('layers-2',15)}</span><span>所有邮箱</span><small>${navCount(x=>x.folder==='inbox')}</small></button>${S.accounts.map(a=>`<button class="mailbox-link ${S.account===a.id?'selected':''}" data-action="account" data-id="${a.id}"><span class="color-dot" style="background:${esc(a.color)}"></span><span>${esc(a.label)}<small>${esc(a.email)}</small></span>${a.sync_error?'<span class="error-dot" title="连接需要处理"></span>':!a.enabled?I('pause',13):''}</button>`).join('')}${!S.accounts.length?'<p class="sidebar-hint">连接邮箱，开始整理来信。</p>':''}</div><div class="sidebar-bottom"><button class="nav-item ${S.view==='settings'?'active':''}" data-action="nav" data-view="settings">${I('settings-2')}<span>设置与连接</span></button><div class="profile-chip">${avatar(null,S.user?.user_metadata?.username||S.user?.email)}<div><strong>${esc(S.user?.user_metadata?.username||'我的账户')}</strong><small>私人工作空间</small></div><button class="icon-btn" data-action="logout" aria-label="退出登录">${I('log-out',17)}</button></div></div></aside>`;}
function render(){if(!S.user)return loginView();$('#app').innerHTML=`<div class="app-shell">${S.mobileNav?'<button class="nav-scrim" data-action="toggle-nav" aria-label="关闭导航"></button>':''}${sidebar()}<main class="workspace"><header class="topbar"><button class="icon-btn mobile-menu" data-action="toggle-nav" aria-label="打开导航">${I('menu')}</button><div class="breadcrumb">我的工作空间 ${I('chevron-right',13)} <span>${esc({inbox:'收件箱',categories:'分类邮件',contacts:'联系人',settings:'设置与连接',sent:'已发送',archive:'归档',trash:'垃圾箱',spam:'垃圾邮件',custom:'原邮箱文件夹',drafts:'草稿箱',reader:'邮件详情',compose:'写邮件'}[S.view]||'邮件')}</span></div><div class="topbar-right"><span class="cloud-state"><span></span>云端私密空间</span><button class="icon-btn" data-action="sync" aria-label="同步所有邮箱" title="同步邮件">${I('refresh-cw',18)}</button></div></header><div id="view-content">${viewHTML()}</div><footer class="workspace-footer"><span>MAIL ATLAS</span><span>自动同步 · 每 5 分钟${S.accounts.length?' · '+S.accounts.length+' 个邮箱':''}</span></footer></main></div>`;iconsNow();if(S.view==='reader')renderEmail();if(S.view==='compose')renderOriginal();}
function pageHead(kicker,title,subtitle,actions=''){return `<div class="page-head"><div><span class="eyebrow">${kicker}</span><h1>${title}</h1>${subtitle?`<p>${subtitle}</p>`:''}</div><div class="head-actions">${actions}</div></div>`;}
function viewHTML(){if(S.view==='reader')return readerHTML();if(S.view==='compose')return composeHTML();if(S.view==='categories')return categoriesHTML();if(S.view==='contacts')return contactsHTML();if(S.view==='settings')return settingsHTML();if(S.view==='drafts')return draftsHTML();return inboxHTML();}
function inboxHTML(){const title=S.starred?'星标邮件':S.category?esc(category(S.category)?.name||'分类邮件'):esc(S.remoteFolder||folderLabels[S.view]||'收件箱');return `<section class="page inbox-page">${pageHead('YOUR DAILY CORRESPONDENCE',title,`${S.account?esc(account(S.account)?.label):'所有邮箱'} · ${S.total} 封邮件`,`${S.view==='inbox'?'<button class="secondary" data-action="ai-classify">'+I('sparkles',16)+' 智能分类</button>':''}<button class="secondary" data-action="export">${I('download',16)} 导出</button>`)}<div class="inbox-toolbar"><div class="search-field">${I('search',18)}<input id="mail-search" aria-label="模糊搜索邮件" placeholder="搜索主题、发件人或正文…" value="${esc(S.query)}"><kbd>⌕</kbd></div><div class="filter-controls"><select id="category-filter" aria-label="邮件类别"><option value="">所有类别</option>${S.categories.map(c=>`<option value="${c.id}" ${S.category===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select><select id="sender-filter" aria-label="发件人"><option value="">所有发件人</option>${S.contacts.map(c=>`<option value="${esc(c.email)}" ${S.sender===c.email?'selected':''}>${esc(c.name||c.email)}</option>`).join('')}</select><button class="filter-toggle ${S.unread?'selected':''}" data-action="unread-filter">${I('list-filter',16)} 未读</button></div></div><div class="list-actions"><label class="check"><input id="select-all" type="checkbox" aria-label="全选本页邮件" ${S.messages.length&&S.selected.size===S.messages.length?'checked':''}><span>${S.selected.size?'已选 '+S.selected.size+' 封':'全部邮件'}</span></label><div>${S.selected.size?`<button class="text-btn" data-action="bulk-read">标为已读</button><button class="text-btn" data-action="bulk-category">更改分类</button>`:''}<button class="text-btn" data-action="sync">${I('refresh-cw',14)} 刷新</button><span class="sort-label">最新在前 ${I('arrow-down',13)}</span></div></div><div id="mail-list">${mailListHTML()}</div><div class="pagination"><span>${S.total?`${S.page*50+1}–${Math.min((S.page+1)*50,S.total)} / ${S.total}`:'暂无邮件'}</span><div>${S.accounts.length?'<button class="text-btn" data-action="load-older">加载更早邮件</button>':''}<button class="icon-btn" data-action="prev-page" ${S.page===0?'disabled':''} aria-label="上一页">${I('chevron-left',17)}</button><button class="icon-btn" data-action="next-page" ${(S.page+1)*50>=S.total?'disabled':''} aria-label="下一页">${I('chevron-right',17)}</button></div></div></section>`;}
function mailListHTML(){if(!S.accounts.length)return `<div class="empty-state onboarding"><span class="empty-icon">${I('mail-plus',38)}</span><span class="eyebrow">ONE INBOX. ALL YOUR MAIL.</span><h2>让你的邮箱，在这里相遇</h2><p>连接 QQ、Gmail、Outlook 或学校邮箱。<br>保留各自身份，在一个收件箱里从容处理。</p><button class="primary" data-action="add-account">${I('plus',17)} 连接第一个邮箱</button><div class="provider-pills"><span>QQ 邮箱</span><span>Gmail</span><span>Outlook</span><span>学校邮箱</span></div></div>`;
 if(!S.messages.length)return `<div class="empty-state"><span class="empty-icon">${I(S.query?'search-x':'inbox',36)}</span><h2>${S.query?'没有找到匹配邮件':'这个文件夹暂无已同步邮件'}</h2><p>${S.query?'试试不同的关键词，或清除筛选条件。':'可以同步邮箱获取来信，或继续加载更早的邮件。'}</p><button class="secondary" data-action="sync">${I('refresh-cw',16)} 同步邮件</button></div>`;
 return `<div class="mail-grid table-head"><span></span><span>邮箱标签</span><span>时间</span><span>${['sent','drafts'].includes(S.view)?'收件人':'发件人'}</span><span>主题</span><span></span></div><div class="mail-rows">${S.messages.map(m=>{const outgoing=['sent','drafts'].includes(S.view),personEmail=outgoing?(m.to_list?.[0]?.address||''):m.from_email,personName=outgoing?(m.to_list?.[0]?.name||personEmail||'尚未填写收件人'):(m.from_name||m.from_email),c=contact(personEmail),cat=category(m.category_id);return `<div class="mail-grid mail-row ${!m.is_read?'unread':''} ${S.selected.has(m.id)?'checked':''}" data-open="${m.id}" tabindex="0" role="button" aria-label="打开 ${esc(m.subject)}"><label class="row-check"><input class="mail-check" type="checkbox" data-id="${m.id}" ${S.selected.has(m.id)?'checked':''} aria-label="选择 ${esc(m.subject)}"></label><div class="row-account">${badge(account(m.account_id))}</div><time>${fmtDate(m.received_at)}</time><div class="row-sender">${avatar(c,personName)}<strong title="${esc(personEmail)}">${esc(c?.name||personName)}</strong></div><div class="row-subject"><div><span class="unread-dot"></span><strong>${esc(m.subject)}</strong>${m.attachments?.length?I('paperclip',14):''}${cat?`<small class="category-label" style="--tag:${esc(cat.color)}">${esc(cat.name)}</small>`:''}${m.ai_error?'<span class="ai-error-mark" title="'+esc(m.ai_error)+'">!</span>':''}</div><p>${esc(m.preview)}</p></div><button class="icon-btn row-star ${m.starred?'starred':''}" data-action="star" data-id="${m.id}" aria-label="${m.starred?'取消星标':'添加星标'}">${I('star',17)}</button></div>`;}).join('')}</div>`;}
function categoriesHTML(){return `<section class="page">${pageHead('A PLACE FOR EVERY MESSAGE','分类邮件','让每一封来信，都有自己的位置。',`<button class="secondary" data-action="ai-classify">${I('sparkles',16)} 分类待处理邮件</button><button class="primary" data-action="add-category">${I('plus',17)} 新建类别</button>`)}<div class="info-strip">${I('sparkles',17)}<span>DeepSeek 根据你设置的类别整理新邮件。结果保存在云端，手动分类会优先保留。</span></div><div class="folder-list"><div class="folder-heading"><span>文件夹</span><span>总邮件数</span><span>未读</span><span>操作</span></div>${S.categories.map(c=>{const matches=x=>x.category_id===c.id&&['inbox','archive','custom'].includes(x.folder);return `<div class="folder-row"><button class="folder-title" data-action="open-category" data-id="${c.id}"><span class="folder-icon" style="--tag:${esc(c.color)}">${I('folder',25)}</span><span><strong>${esc(c.name)}</strong><small>${esc(c.description||'自定义邮件类别')}</small></span></button><span>${navCount(matches)}</span><span class="unread-number">${navCount(x=>matches(x)&&!x.is_read)}</span><div><button class="text-btn" data-action="category-read" data-id="${c.id}">全部已读</button><button class="icon-btn" data-action="edit-category" data-id="${c.id}" aria-label="设置 ${esc(c.name)}">${I('settings-2',17)}</button></div></div>`;}).join('')}</div><p class="section-footnote">新增或修改类别后，AI 缓存会按新规则分批更新；你手动指定的分类始终保留。</p></section>`;}
function contactsHTML(){const q=S.contactQuery||'',group=S.contactGroup||'';const people=S.contacts.filter(c=>(!group||c.group_name===group)&&(!q||fuzzy(c.name+' '+c.email+' '+c.second_email+' '+c.organization,q)));return `<section class="page">${pageHead('PEOPLE BEHIND THE MESSAGES','联系人','从一封邮件，到每一次熟悉的交流。',`<button class="secondary" data-action="ai-classify">${I('sparkles',16)} 智能分组</button><button class="primary" data-action="add-contact">${I('user-plus',17)} 新建联系人</button><button class="secondary" data-action="find-photos">${I('camera',16)} 补全缺失头像</button>`)}<div class="contacts-toolbar"><div class="search-field">${I('search',17)}<input id="contact-search" placeholder="搜索姓名、邮箱或机构…" aria-label="搜索联系人" value="${esc(q)}"></div><select id="contact-group-filter" aria-label="联系人分组"><option value="">所有分组</option>${[...new Set(['未分类',...(S.settings.contact_groups||[]),...S.contacts.map(c=>c.group_name)])].map(g=>`<option ${group===g?'selected':''}>${esc(g)}</option>`).join('')}</select><span class="muted">${people.length} 位联系人</span></div><div class="contacts-grid">${people.map(c=>`<article class="contact-card"><div class="contact-card-top">${avatar(c,c.email,true)}<button class="icon-btn" data-action="edit-contact" data-id="${c.id}" aria-label="编辑 ${esc(c.name||c.email)}">${I('pencil',16)}</button></div><h3>${esc(c.name||c.email.split('@')[0])}</h3><p>${esc(c.organization||'尚未填写机构')}</p><span class="contact-group">${esc(c.group_name)}</span><a href="mailto:${esc(c.email)}">${esc(c.email)}</a>${c.second_email?`<small>${esc(c.second_email)}</small>`:''}<small class="photo-status">${photoStatus(c)}</small>${c.photo_source_url?`<a class="photo-credit" href="${esc(c.photo_source_url)}" target="_blank" rel="noopener noreferrer">头像来源 ↗</a>`:''}${!c.photo_path?`<button class="text-btn" data-action="find-photo" data-id="${c.id}" data-retry="${c.photo_lookup_status?'true':'false'}">${c.photo_lookup_status?'重新查找照片':'查找匹配照片'}</button>`:''}<div class="contact-card-actions"><button class="text-btn" data-action="write-contact" data-id="${c.id}">${I('mail',15)} 写邮件</button><button class="text-btn" data-action="filter-contact" data-id="${c.id}">查看来信 ${I('arrow-up-right',14)}</button></div></article>`).join('')||'<div class="empty-state"><span class="empty-icon">'+I('contact-round',34)+'</span><h2>让熟悉的人，更好找到</h2><p>同步邮件会自动收集发件人，也可以手动添加联系人。</p></div>'}</div>${S.contacts.length>=1000?'<p class="section-footnote">联系人较多，当前最多显示5000位。</p>':''}</section>`;}
function settingsHTML(){return `<section class="page settings-page">${pageHead('MAKE IT YOURS','设置与连接','为每个邮箱，保留独特的身份。')}<section class="settings-block"><div class="block-heading"><div><h2>已连接邮箱</h2><p>自定义标签与颜色，管理同步和授权。</p></div><button class="primary" data-action="add-account">${I('plus',17)} 添加邮箱</button></div>${S.accounts.map(a=>`<div class="account-setting"><span class="account-setting-icon" style="--tag:${esc(a.color)}">${I('mail',23)}</span><div class="account-description"><strong>${esc(a.label)} ${badge(a)}</strong><p>${esc(a.email)}</p><small class="${a.sync_error?'error-text':''}">${a.sync_error?esc(a.sync_error):a.last_sync?'上次同步 '+fmtDate(a.last_sync,true):'等待首次同步'}${!a.enabled?' · 已暂停':''}</small></div><div class="account-buttons"><button class="text-btn" data-action="test-account" data-id="${a.id}">测试连接</button>${['gmail','outlook'].includes(a.provider)?`<button class="text-btn" data-action="authorize" data-id="${a.id}">OAuth 授权</button>`:''}<button class="icon-btn" data-action="toggle-account" data-id="${a.id}" aria-label="${a.enabled?'暂停':'启用'}同步">${I(a.enabled?'pause':'play',17)}</button><button class="icon-btn" data-action="edit-account" data-id="${a.id}" aria-label="编辑邮箱">${I('pencil',17)}</button><button class="icon-btn" data-action="disconnect" data-id="${a.id}" aria-label="断开连接">${I('unplug',17)}</button></div></div>`).join('')||'<div class="small-empty">还没有连接邮箱。添加后即可自动接收邮件。</div>'}</section><section class="settings-block"><div class="block-heading"><div><h2>AI 与阅读偏好</h2><p>DeepSeek 由服务端调用，密钥不发送到浏览器。</p></div><span class="mini-pill">DEEPSEEK</span></div><form id="preferences-form"><label class="switch-row"><span><strong>新邮件自动分类</strong><small>把邮件文本与联系人摘要发送给 DeepSeek；结果存储后不重复分类。</small></span><input type="checkbox" name="auto_classify" ${S.settings.auto_classify?'checked':''}></label><label class="switch-row"><span><strong>自动补全联系人头像</strong><small>核对姓名与机构官网邮箱，明确匹配才保存照片；无匹配时留空并缓存结果。</small></span><input type="checkbox" name="auto_contact_photos" ${S.settings.auto_contact_photos!==false?'checked':''}></label><div class="form-grid"><label>默认翻译语言<select name="translation_language">${languageOptions(S.settings.translation_language)}</select></label><label>联系人分组（用逗号分隔）<input name="contact_groups" value="${esc((S.settings.contact_groups||[]).join('，'))}"></label></div><label>邮件签名<textarea name="signature" rows="4" placeholder="新邮件和回复会自动带上这段签名。">${esc(S.settings.signature||'')}</textarea></label><div class="form-footer"><span class="muted">手动修改的分类和联系人分组不会被自动覆盖。</span><button class="primary" type="submit">保存偏好</button></div></form></section><section class="settings-block"><div class="block-heading"><div><h2>账户与导出</h2><p>${esc(S.user.email)} · 与文献管理系统共用账号</p></div></div><div class="account-preferences"><button class="secondary" data-action="change-password">${I('key-round',16)} 修改密码</button><button class="secondary" data-action="export">${I('download',16)} 导出邮件</button><a class="secondary" href="https://kmluo98.github.io/paper-atlas/" target="_blank" rel="noopener">${I('book-open',16)} 文献管理系统 ${I('arrow-up-right',14)}</a></div><p class="section-footnote">后台每5分钟检查邮箱；收件箱、已发送、草稿、归档和垃圾邮件按文件夹分批同步，每次最多30封（Outlook 20封），历史邮件可在对应文件夹继续加载。附件单封总计不超过12MB，接收邮件原文不超过25MB。通用邮箱需开启IMAP与SMTP，使用993 / 465加密端口。</p></section></section>`;}
const languageOptions=(selected='简体中文')=>['简体中文','繁體中文','English','日本語','한국어','Français','Deutsch','Español'].map(l=>`<option ${l===selected?'selected':''}>${l}</option>`).join('');
function readerHTML(){const m=S.current;if(!m)return '<div class="empty-state">正在读取邮件…</div>';const c=contact(m.from_email),a=account(m.account_id);return `<section class="reader-page"><div class="reader-toolbar"><button class="secondary" data-action="back">${I('arrow-left',17)} 返回邮件列表</button><div><button class="icon-btn ${m.starred?'starred':''}" data-action="star" data-id="${m.id}" aria-label="切换星标">${I('star',18)}</button><button class="icon-btn" data-action="move" data-folder="${m.folder==='archive'?'inbox':'archive'}" aria-label="归档或恢复">${I(m.folder==='archive'?'archive-restore':'archive',18)}</button><button class="icon-btn" data-action="move" data-folder="${m.folder==='trash'?'inbox':'trash'}" aria-label="移入垃圾箱或恢复">${I(m.folder==='trash'?'undo-2':'trash-2',18)}</button><button class="icon-btn" data-action="export-current" aria-label="导出这封邮件">${I('download',18)}</button><button class="primary" data-action="${m.folder==='drafts'?'copy-remote-draft':'reply'}">${I('reply',17)} ${m.folder==='drafts'?'复制为本站草稿':'回复'}</button></div></div><div class="reader-columns"><article class="email-paper"><div class="email-subject"><div>${badge(a)}<span class="quiet-label">${folderLabels[m.folder]||'收到的邮件'}</span></div><h1>${esc(m.subject)}</h1><div class="email-from">${avatar(c,m.from_name||m.from_email)}<div><strong>${esc(c?.name||m.from_name||m.from_email)}</strong><span>${esc(m.from_email)}</span></div><time>${fmtDate(m.received_at,true)}</time></div></div><div class="email-content"><iframe id="email-frame" title="邮件正文" sandbox="allow-popups allow-popups-to-escape-sandbox" referrerpolicy="no-referrer"></iframe></div>${m.html_body?'<div class="remote-image-note">'+I('image-off',15)+' 外部图片默认关闭<button class="text-btn" data-action="load-images">加载图片</button></div>':''}${m.attachments?.length?`<div class="attachments"><h3>${I('paperclip',16)} 附件 · ${m.attachments.length}</h3>${m.attachments.map(x=>`<button class="attachment" data-action="download-attachment" data-index="${x.index}">${I('file',21)}<span><strong>${esc(x.filename)}</strong><small>${bytes(x.size)}</small></span>${I('download',15)}</button>`).join('')}</div>`:''}<div class="email-bottom"><button class="secondary" data-action="reply">${I('reply',17)} 回复邮件</button><button class="text-btn" data-action="mark-unread">标为未读</button></div></article><aside class="reader-aside"><section class="info-card"><div class="card-label">${I('info',16)} 邮件信息</div><div class="sender-profile">${avatar(c,m.from_name||m.from_email,true)}<div><h3>${esc(c?.name||m.from_name||m.from_email)}</h3><p>${esc(c?.organization||m.from_email)}</p></div><button class="icon-btn" data-action="reader-contact" aria-label="编辑联系人">${I('pencil',16)}</button></div>${c&&!c.photo_path?`<button class="text-btn" data-action="find-photo" data-id="${c.id}" data-retry="${c.photo_lookup_status?'true':'false'}">查找匹配照片</button><small class="photo-status">${photoStatus(c)}</small>`:''}${c?.photo_source_url?`<a class="photo-credit" href="${esc(c.photo_source_url)}" target="_blank" rel="noopener noreferrer">头像来源 ↗</a>`:''}<dl><dt>发件人</dt><dd>${esc(m.from_email)}</dd><dt>所属邮箱</dt><dd>${badge(a)}<span>${esc(a?.email)}</span></dd><dt>收件人</dt><dd>${esc(m.to_list?.map(x=>x.address).join('，')||'—')}</dd>${m.cc_list?.length?'<dt>抄送</dt><dd>'+esc(m.cc_list.map(x=>x.address).join('，'))+'</dd>':''}<dt>时间</dt><dd>${fmtDate(m.received_at,true)}</dd>${c?.second_email?'<dt>第二邮箱</dt><dd>'+esc(c.second_email)+'</dd>':''}${c?.phone?'<dt>电话</dt><dd>'+esc(c.phone)+'</dd>':''}${c?.group_name?'<dt>联系人分组</dt><dd>'+esc(c.group_name)+'</dd>':''}</dl><label class="reader-category">邮件类别<select id="reader-category"><option value="">未分类</option>${S.categories.map(c=>`<option value="${c.id}" ${m.category_id===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><div class="category-source">${m.category_source==='manual'?'手动分类 · 已保存':m.classified_at?'AI 分类结果 · 已缓存':'等待分类'}${m.ai_error?'<p class="error-text">'+esc(m.ai_error)+'</p>':''}</div><button class="text-btn" data-action="reclassify">${I('sparkles',14)} 重新用 AI 分类</button></section><section class="info-card translation-card"><div class="card-label">${I('languages',17)} 邮件翻译 <span>DEEPSEEK</span></div><div class="translation-controls"><select id="translate-language" aria-label="翻译目标语言">${languageOptions(S.language)}</select><button class="primary" data-action="translate">翻译 ${I('arrow-right',15)}</button></div><div id="translation-result" class="translation-result">${S.translation?esc(S.translation):'<div class="translation-empty">'+I('languages',29)+'<p>读懂每一种语言里的来信</p><small>默认翻译成中文，译文自动保存。</small></div>'}</div></section></aside></div></section>`;}
function emailDocument(m,images=false){const html=m.html_body?DOMPurify.sanitize(m.html_body,{WHOLE_DOCUMENT:false,FORBID_TAGS:['script','iframe','form','input','button','object','embed','video','audio','link','meta','base','svg','math'],FORBID_ATTR:['srcset','ping','autofocus','formaction']}).replace(/<a\s/gi,'<a target="_blank" rel="noopener noreferrer" '):`<div style="white-space:pre-wrap">${esc(m.text_body||'（此邮件没有正文）')}</div>`;return `<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data: blob:${images?' https:':''}; font-src 'none'; base-uri 'none'; form-action 'none'"><style>html{overflow-wrap:anywhere}body{margin:0;padding:8px 2px 32px;color:#343b39;font:15px/1.9 -apple-system,BlinkMacSystemFont,'Segoe UI','Microsoft YaHei',sans-serif}img{max-width:100%;height:auto}table{max-width:100%}a{color:#315b52}pre{white-space:pre-wrap}</style></head><body>${html}</body></html>`;}
function renderEmail(images=false){const frame=$('#email-frame');if(frame&&S.current)frame.srcdoc=emailDocument(S.current,images);}
function renderOriginal(){const frame=$('#original-frame');if(frame&&S.compose?.original)frame.srcdoc=emailDocument(S.compose.original);}
function composeHTML(){const d=S.compose;if(!d)return '';return `<section class="compose-page"><div class="reader-toolbar"><button class="secondary" data-action="leave-compose">${I('arrow-left',17)} 返回</button><span class="muted">${d.draftId?'草稿已保存':'编辑后可保存为云端草稿'}</span></div><div class="compose-columns"><section class="compose-editor"><header><span class="eyebrow">A THOUGHTFUL RESPONSE</span><h1>${d.reply_id?'回复邮件':'写一封新邮件'}</h1></header><form id="compose-form"><div class="compose-fields"><label>发件邮箱<select name="account_id" required>${S.accounts.map(a=>`<option value="${a.id}" ${d.account_id===a.id?'selected':''}>${esc(a.label)} · ${esc(a.email)}</option>`).join('')}</select></label><label>收件人<input name="to" type="text" required placeholder="多个邮箱用逗号分隔" value="${esc(d.to)}"></label><div class="form-grid"><label>抄送<input name="cc" placeholder="选填" value="${esc(d.cc||'')}"></label><label>密送<input name="bcc" placeholder="选填" value="${esc(d.bcc||'')}"></label></div><label>主题<input name="subject" required value="${esc(d.subject)}" placeholder="输入邮件主题"></label></div><textarea name="body" id="compose-body" required placeholder="写下你想说的话…">${esc(d.body)}</textarea><div class="compose-attachments">${d.attachments?.map((x,i)=>`<span>${I('paperclip',13)} ${esc(x.filename)}<button type="button" class="icon-btn small" data-action="remove-attachment" data-index="${i}" aria-label="移除附件">${I('x',13)}</button></span>`).join('')||''}</div><div class="compose-bottom"><label class="secondary file-button">${I('paperclip',16)} 附件<input id="compose-file" type="file" multiple hidden></label><button type="button" class="secondary" data-action="save-draft">${I('save',16)} 保存草稿</button><button class="primary" type="submit">发送邮件 ${I('send',16)}</button></div></form></section><aside class="compose-context">${d.original?`<section class="original-card"><div class="card-label">${I('mail-open',17)} 原邮件</div><h3>${esc(d.original.subject)}</h3><p>${esc(d.original.from_name||d.original.from_email)} · ${fmtDate(d.original.received_at,true)}</p><iframe id="original-frame" title="回复参考原邮件" sandbox="allow-popups allow-popups-to-escape-sandbox" referrerpolicy="no-referrer"></iframe></section>`:`<div class="new-mail-note">${I('feather',29)}<h3>从一句想法，到一封好邮件</h3><p>写下关键词，让 DeepSeek 帮你组织语言。<br>确认后再填入正文。</p></div>`}<section class="ai-compose-card"><div class="card-label">${I('sparkles',18)} AI 写信助手<span>DEEPSEEK</span></div><p>${d.original?'已读取右侧原邮件，作为回复背景。':'根据主题和你提供的要点生成邮件。'}</p><label>关键词 / 回复要点<textarea id="ai-keywords" rows="3" placeholder="例如：感谢邀请，下周三下午有空，请对方确认会议地点">${esc(d.keywords||'')}</textarea></label><div class="ai-generate-row"><select id="ai-language" aria-label="生成邮件的语言">${languageOptions(d.aiLanguage||'简体中文')}</select><button class="primary" data-action="generate-draft">${I('sparkles',16)} 生成草稿</button></div>${d.proposal?`<div class="ai-proposal"><span class="eyebrow">待你确认的建议</span><div>${esc(d.proposal)}</div><button class="secondary" data-action="accept-proposal">${I('check',16)} 确认并填入正文</button></div>`:''}</section></aside></div></section>`;}
function draftsHTML(){return `<section class="page">${pageHead('WORDS IN PROGRESS','草稿箱','还没寄出的想法，在这里妥善保存。',`<button class="primary" data-action="compose">${I('square-pen',16)} 新建邮件</button>`)}<h2 class="draft-section-title">本站草稿</h2><div class="draft-list">${S.drafts.map(d=>`<article><button class="draft-open" data-action="open-draft" data-id="${d.id}"><span class="draft-icon">${I('file-pen-line',24)}</span><span><strong>${esc(d.data.subject||'（无主题草稿）')}</strong><small>${esc(d.data.to||'尚未填写收件人')} · ${fmtDate(d.updated_at,true)}</small><p>${esc(d.data.body?.slice(0,100)||'尚未填写正文')}</p></span></button><button class="icon-btn" data-action="delete-draft" data-id="${d.id}" aria-label="删除草稿">${I('trash-2',17)}</button></article>`).join('')||'<div class="empty-state"><span class="empty-icon">'+I('file-pen-line',35)+'</span><h2>还没有本站草稿</h2><p>写信时点击“保存草稿”，下次可以接着写。</p></div>'}</div><h2 class="draft-section-title">原邮箱草稿 · ${S.total} 封</h2><p class="section-footnote">可打开阅读并复制为本站草稿继续编辑，附件需重新添加。</p><div class="list-actions"><button class="text-btn" data-action="sync">同步原邮箱草稿</button><button class="text-btn" data-action="load-older">加载更早草稿</button></div>${mailListHTML()}<div class="pagination"><span>${S.total} 封</span><button class="text-btn" data-action="prev-page" ${S.page===0?'disabled':''}>上一页</button><button class="text-btn" data-action="next-page" ${(S.page+1)*50>=S.total?'disabled':''}>下一页</button></div></section>`;}
async function loadList(rerender=true){const seq=++S.listRequest;const result=await api('list',{folder:S.folder,remote_folder:S.remoteFolder,account_id:S.account||null,category_id:S.category||null,sender:S.sender,query:S.query,unread:S.unread,starred:S.starred,offset:S.page*50,limit:50});if(seq!==S.listRequest)return;Object.assign(S,result);S.selected.clear();if(rerender)render();}
async function navigate(view,extra={}){if(S.view==='compose'&&S.compose&&(S.compose.body.trim()||S.compose.to.trim()))await saveDraft(false);S.view=view;S.mobileNav=false;S.current=null;S.compose=null;S.starred=false;S.category='';S.sender='';S.query='';S.unread=false;S.page=0;S.remoteFolder='';S.folder=listViews.includes(view)?view:'inbox';Object.assign(S,extra);if(listViews.includes(view))await loadList(false);render();window.scrollTo(0,0);if(listViews.includes(view)&&view!=='inbox')syncAll(false,true,{folder:S.folder,remote_folder:S.remoteFolder}).catch(error);}
async function syncAll(older=false,quiet=false,target=null){if(S.syncing)return;const accounts=S.accounts.filter(a=>a.enabled&&(!S.account||a.id===S.account));if(!accounts.length){if(!quiet)toast('请先连接并启用邮箱');return;}S.syncing=true;let n=0,failures=0,busy=0,missing=0;try{if(!quiet)toast(older?'正在加载更早的邮件…':'正在检查邮箱来信…');for(const a of accounts){try{const scope=target||(quiet?{}:{folder:S.folder==='all'?'inbox':S.folder,remote_folder:S.remoteFolder});const r=await api('sync',{id:a.id,older,...scope});n+=r.added||0;if(r.busy)busy++;if(r.missing_folder)missing++;if(r.folder_errors?.length){failures++;if(!quiet)toast(r.folder_errors.join('；'),true);}if(r.ai_error&&!quiet)toast('邮件已同步；'+r.ai_error,true);}catch(e){failures++;if(!quiet)error(Error(a.label+'：'+e.message));}}await bootstrap();if(listViews.includes(S.view))await loadList(false);if(!['reader','compose'].includes(S.view))render();if(!quiet)toast(n?`已同步 ${n} 封邮件`:failures?'部分文件夹同步失败，请在设置查看原因':busy?'邮箱正在后台同步，请稍后刷新':missing?'服务商未提供对应文件夹':'已同步，暂无新邮件');}finally{S.syncing=false;}}
async function openMail(id){S.previous={view:S.view,folder:S.folder,remoteFolder:S.remoteFolder,account:S.account,category:S.category,query:S.query,sender:S.sender,page:S.page,unread:S.unread,starred:S.starred};const r=await api('get',{id});S.current=r.message;S.view='reader';S.translation=r.translations?.[S.language]||'';render();window.scrollTo(0,0);if(!r.message.is_read)try{await api('message_patch',{id,is_read:true});S.current.is_read=true;await bootstrap();}catch(e){toast('邮件已打开，但已读状态同步失败：'+e.message,true);}}
async function patchMessage(id,patch){await api('message_patch',{id,...patch});if(S.current?.id===id)Object.assign(S.current,patch);const m=S.messages.find(m=>m.id===id);if(m)Object.assign(m,patch);await bootstrap();render();}
async function openCompose(original=null,draft=null){if(!S.accounts.length){accountModal();return;}const data=draft?.data||{};S.compose={account_id:data.account_id||original?.account_id||S.account||S.accounts[0]?.id,to:data.to||(original?(original.reply_to||original.from_email):''),cc:data.cc||'',bcc:data.bcc||'',subject:data.subject||(original?(/^re:/i.test(original.subject)?original.subject:'Re: '+original.subject):''),body:data.body||((S.settings.signature?'\n\n'+S.settings.signature:'')),reply_id:data.reply_id||original?.id||null,original,attachments:[],draftId:draft?.id||null,key:crypto.randomUUID(),proposal:'',keywords:'',aiLanguage:'简体中文'};S.view='compose';S.mobileNav=false;render();}
function composeData(){const f=$('#compose-form');if(f)Object.assign(S.compose,Object.fromEntries(new FormData(f)));return S.compose;}
async function saveDraft(notify=true){const d=composeData();if(!d)return;const r=await api('draft_save',{id:d.draftId,data:d});d.draftId=r.id;await bootstrap();if(notify){if(d.attachments.length)toast('正文已保存。附件仅在当前编辑页保留，重新打开草稿需再添加。');else toast('草稿已保存到云端');render();}}
function accountModal(a=null){const service=a?.provider==='gmail'?'gmail':a?.provider==='outlook'?'outlook':a?.config?.imap_host==='imap.qq.com'?'qq':'school';modal(a?'编辑邮箱连接':'连接一个邮箱',`<form id="account-form"><input type="hidden" name="id" value="${a?.id||''}"><div class="form-grid"><label>邮箱服务商<select name="service" id="provider-select" ${a?'disabled':''}><option value="qq" ${service==='qq'?'selected':''}>QQ 邮箱</option><option value="gmail" ${service==='gmail'?'selected':''}>Gmail</option><option value="outlook" ${service==='outlook'?'selected':''}>Outlook / Microsoft 365</option><option value="school" ${service==='school'?'selected':''}>学校邮箱 / 其他 IMAP</option></select></label><label>邮箱地址<input name="email" type="email" required value="${esc(a?.email||'')}" ${a?'readonly':''} placeholder="name@example.com" autocomplete="off"></label></div><div class="form-grid"><label>自定义标签<input name="label" required maxlength="40" placeholder="例如：工作、学校、私人" value="${esc(a?.label||'')}"></label><label>标签颜色<div class="color-input"><input type="color" name="color" value="${esc(a?.color||'#4f7a6f')}"><span>列表显示对应的文字与底色</span></div></label></div><div id="provider-fields"></div><div class="form-error" role="alert"></div><div class="modal-footer"><button class="secondary" type="button" data-action="close-modal">取消</button><button class="primary" type="submit">${a?'保存连接':'保存并连接'} ${I('arrow-right',15)}</button></div></form>`,true);providerFields(service,a);}
function providerFields(service,a){const host=a?.config||{};const oauth=`<details ${service==='outlook'?'open':''}><summary>OAuth 应用配置${service==='gmail'?'（也可用应用专用密码）':''}</summary><p class="form-help">${service==='gmail'?'在 Google Cloud 创建 Web OAuth 客户端，并将自己的 Gmail 加入测试用户。':'在 Microsoft Entra 注册应用，允许你的账户类型；添加 Mail.ReadWrite、Mail.Send 和 offline_access 委托权限。'}</p><label>Client ID<input name="client_id" autocomplete="off" placeholder="${a?'重新配置时填写；留空保持现有配置':'OAuth 应用 Client ID'}"></label><label>Client Secret<input name="client_secret" type="password" autocomplete="new-password" placeholder="仅发送到加密的后端存储"></label><label>授权回调地址<input readonly value="https://fubuikclgsgcxviymshr.supabase.co/functions/v1/mail-api" class="monospace"></label><p class="form-help">保存后点击“OAuth 授权”。服务商的应用审核、管理员限制和授权由邮箱服务商控制。</p></details>`;
 $('#provider-fields').innerHTML=(service==='qq'?`<div class="info-strip">${I('shield-check',17)}<span>在 QQ 邮箱设置 → 账号中开启 IMAP/SMTP，使用生成的授权码。</span></div>`:'')+(service!=='outlook'?`<label>${service==='gmail'?'Google 应用专用密码':service==='qq'?'QQ 邮箱授权码':'邮箱授权码 / 应用密码'}<input name="password" type="password" autocomplete="new-password" placeholder="${a?'留空保留已存凭据':'不会保存在浏览器或 GitHub'}"></label>`:'')+(service==='school'?`<div class="form-grid"><label>IMAP 服务器<input name="imap_host" required value="${esc(host.imap_host||'')}" placeholder="imap.university.edu.cn"></label><label>SMTP 服务器<input name="smtp_host" required value="${esc(host.smtp_host||'')}" placeholder="smtp.university.edu.cn"></label></div><label>登录用户名（默认邮箱地址）<input name="username" value="${esc(host.username||'')}" placeholder="部分学校要求单独的用户名"></label><p class="form-help">使用加密端口 IMAP 993 / SMTP 465。若学校邮箱为 Microsoft 365，请选 Outlook 授权；仅提供587端口的邮箱需另配邮件网关，当前无法直接发送。</p>`:'')+(['gmail','outlook'].includes(service)?oauth:'');iconsNow();}
function categoryModal(c=null){modal(c?'编辑邮件类别':'新建邮件类别',`<form id="category-form"><input type="hidden" name="id" value="${c?.id||''}"><label>类别名称<input name="name" required maxlength="60" value="${esc(c?.name||'')}" placeholder="例如：学术交流"></label><label>分类说明<textarea name="description" rows="3" placeholder="告诉 AI 哪些邮件应该放进这个类别。">${esc(c?.description||'')}</textarea></label><label>类别颜色<input name="color" type="color" value="${esc(c?.color||'#638b82')}"></label><div class="form-error"></div><div class="modal-footer">${c?`<button type="button" class="text-btn danger" data-action="delete-category" data-id="${c.id}">删除类别</button>`:''}<button class="primary" type="submit">保存类别</button></div></form>`);}
function contactModal(c=null){modal(c?'编辑联系人':'新建联系人',`<form id="contact-form"><input type="hidden" name="id" value="${c?.id||''}"><div class="contact-edit-photo">${avatar(c,c?.email,true)}<label class="secondary file-button">${I('camera',16)} 选择照片<input name="photo_file" type="file" accept="image/png,image/jpeg,image/webp" hidden></label><small>PNG / JPEG / WebP，最大 2MB</small>${c?.id&&c.photo_path?`<button class="text-btn" type="button" data-action="remove-photo" data-id="${c.id}">移除照片</button>`:''}</div><p class="photo-status">${photoStatus(c||{})}。保存姓名和机构后，可在联系人卡片查找匹配照片。</p><div class="form-grid"><label>姓名<input name="name" value="${esc(c?.name||'')}" placeholder="联系人姓名"></label><label>邮箱<input name="email" type="email" required value="${esc(c?.email||'')}"></label><label>第二邮箱<input name="second_email" type="email" value="${esc(c?.second_email||'')}"></label><label>机构<input name="organization" value="${esc(c?.organization||'')}"></label><label>电话<input name="phone" value="${esc(c?.phone||'')}"></label><label>分组<select name="group_name">${[...new Set(['未分类',...(S.settings.contact_groups||[]),...(c?[c.group_name]:[])])].map(g=>`<option ${c?.group_name===g?'selected':''}>${esc(g)}</option>`).join('')}</select></label></div><label>备注<textarea name="notes" rows="3">${esc(c?.notes||'')}</textarea></label><div class="form-error"></div><div class="modal-footer"><button class="primary" type="submit">保存联系人</button></div></form>`,true);}
function exportModal(){modal('导出邮件内容',`<form id="export-form"><p class="muted">导出邮件正文与信息。EML / MBOX 保留原始邮件及附件。</p><label>导出范围<select name="scope">${S.current?'<option value="current">当前邮件</option>':''}${S.selected.size?'<option value="selected">已选择的 '+S.selected.size+' 封邮件</option>':''}<option value="filtered">当前筛选结果（${S.total} 封）</option><option value="all">所有已同步邮件（含已发送和垃圾箱）</option></select></label><label>格式<select name="format"><option value="json">JSON · 结构化完整正文</option><option value="csv">CSV · 可用 Excel 打开</option><option value="mbox">MBOX · 原始邮件归档</option><option value="eml">EML · 单封原始邮件</option></select></label><p class="form-help">仅导出本站已同步的邮件；需要更早邮件时请先加载历史记录。大批量导出需保持此页面打开。</p><div class="export-progress" aria-live="polite"></div><div class="form-error"></div><div class="modal-footer"><button class="primary" type="submit">${I('download',16)} 开始导出</button></div></form>`);}
async function doExport(f){const data=Object.fromEntries(new FormData(f));const progress=$('.export-progress',f);let list=[];if(data.scope==='current')list=[S.current];else if(data.scope==='selected')list=S.messages.filter(m=>S.selected.has(m.id));else{const folders=data.scope==='all'?['inbox','sent','archive','trash','drafts','spam','custom']:[S.folder];for(const folder of folders){for(let offset=0;;offset+=100){const r=await api('list',{...(data.scope==='all'?{}:{account_id:S.account||null,remote_folder:S.remoteFolder,category_id:S.category||null,sender:S.sender,query:S.query,unread:S.unread,starred:S.starred}),folder,limit:100,offset});list.push(...r.messages);progress.textContent=`已获取 ${list.length} 封邮件索引…`;if(offset+100>=r.total)break;}}}if(!list.length)throw Error('没有可导出的邮件');if(data.format==='eml'&&list.length!==1)throw Error('EML 格式请选择一封邮件；批量请使用 MBOX');const output=[];for(let i=0;i<list.length;i++){progress.textContent=`正在导出 ${i+1} / ${list.length}…`;if(['mbox','eml'].includes(data.format)){const r=await api('raw',{id:list[i].id});const raw=from64(r.content);if(data.format==='eml'){download(raw,r.filename,'message/rfc822');closeModal();return;}output.push(mboxEntry(new TextDecoder().decode(raw)));}else{const r=await api('get',{id:list[i].id});const {raw_path,user_id,...safe}=r.message;output.push({...safe,account:account(safe.account_id)?.label||'',category:category(safe.category_id)?.name||'未分类'});}}const date=new Date().toISOString().slice(0,10);if(data.format==='mbox')download(output.join(''),'MailAtlas-'+date+'.mbox','application/mbox');else if(data.format==='csv')download(exportCSV(output,S.accounts,S.categories),'MailAtlas-'+date+'.csv','text/csv;charset=utf-8');else download(JSON.stringify({exported_at:new Date().toISOString(),messages:output},null,2),'MailAtlas-'+date+'.json','application/json');closeModal();toast('邮件导出完成');}
async function classifyPending(){let count=0,r={};for(let i=0;i<8;i++){r=await api('classify');count+=r.count||0;if(r.busy||!r.has_more)break;}return {...r,count};}
async function bulkPatch(patch){const ids=[...S.selected];let count=0;for(const id of ids){await api('message_patch',{id,...patch});count++;}await bootstrap();await loadList();toast(`已更新 ${count} 封邮件`);}
async function handleAction(action,el){const id=el?.dataset.id;switch(action){
 case 'auth-login':authMode='login';loginView();break;case 'auth-register':authMode='register';loginView();break;
 case 'toggle-password':{const input=$('.password-input input');input.type=input.type==='password'?'text':'password';break;}
 case 'forgot':modal('找回密码',`<p>账号与文献管理系统共用。请在文献管理系统登录页选择“忘记密码”，通过邮箱重置后，再回到这里登录。</p><div class="modal-footer"><a class="primary" href="https://kmluo98.github.io/paper-atlas/" target="_blank" rel="noopener">打开文献管理系统 ${I('arrow-up-right',16)}</a></div>`);break;
 case 'close-modal':closeModal();break;case 'toggle-nav':S.mobileNav=!S.mobileNav;render();break;
 case 'home':case 'back':if(S.previous&&action==='back'){const p=S.previous;await navigate(p.view,p);}else await navigate('inbox');break;
 case 'nav':await navigate(el.dataset.view);break;case 'favorites':await navigate('inbox',{starred:true});break;
 case 'account':await navigate(listViews.includes(S.view)?S.view:'inbox',{account:id||''});break;
 case 'remote-folder':await navigate('custom',{account:id,remoteFolder:el.dataset.path});break;
 case 'sync':await syncAll();break;case 'load-older':await syncAll(true);break;
 case 'unread-filter':S.unread=!S.unread;S.page=0;await loadList();break;
 case 'prev-page':if(S.page>0){S.page--;await loadList();}break;case 'next-page':if((S.page+1)*50<S.total){S.page++;await loadList();}break;
 case 'add-account':accountModal();break;case 'edit-account':accountModal(account(id));break;
 case 'test-account':await api('account_test',{id});toast('收信、发信连接验证通过；测试未发送邮件');break;
 case 'authorize':{const r=await api('oauth_start',{id});window.location.assign(r.url);break;}
 case 'toggle-account':await api('account_toggle',{id,enabled:!account(id).enabled});await bootstrap();render();break;
 case 'disconnect':modal('断开邮箱连接',`<p>将清除“${esc(account(id)?.label)}”保存的授权凭据，停止同步。已经同步的邮件会保留。</p><div class="modal-footer"><button class="secondary" data-action="close-modal">取消</button><button class="primary" data-action="confirm-disconnect" data-id="${id}">断开连接</button></div>`);break;
 case 'confirm-disconnect':await api('account_disconnect',{id});closeModal();await bootstrap();render();toast('邮箱已断开，已有邮件已保留');break;
 case 'add-category':categoryModal();break;case 'edit-category':categoryModal(category(id));break;
 case 'delete-category':await api('category_delete',{id});closeModal();await bootstrap();render();toast('类别已删除，邮件保留为未分类');break;
 case 'open-category':await navigate('inbox',{category:id,folder:'all'});break;
 case 'category-read':{let count=0;for(;;){const r=await api('mark_category_read',{id});count+=r.count;if(!r.has_more)break;}await bootstrap();render();toast(`已将 ${count} 封邮件标为已读`);break;}
 case 'ai-classify':{const r=await classifyPending();await bootstrap();if(listViews.includes(S.view))await loadList(false);render();toast(r.busy?'分类正在后台处理，稍后会保存结果':r.count?`已保存 ${r.count} 封邮件的分类${r.has_more?'，其余将继续分批处理':''}`:'当前没有待处理邮件；联系人分组也已检查');break;}
 case 'bulk-read':await bulkPatch({is_read:true});break;
 case 'bulk-category':modal('批量更改分类',`<form id="bulk-category-form"><label>类别<select name="category_id"><option value="">未分类</option>${S.categories.map(c=>`<option value="${c.id}">${esc(c.name)}</option>`).join('')}</select></label><p class="muted">将更新选中的 ${S.selected.size} 封邮件，并保留为手动分类。</p><div class="modal-footer"><button class="primary" type="submit">保存分类</button></div></form>`);break;
 case 'star':{const m=S.current?.id===id?S.current:S.messages.find(x=>x.id===id);await patchMessage(id,{starred:!m.starred});break;}
 case 'move':await api('message_patch',{id:S.current.id,folder:el.dataset.folder});toast('邮件已移动');await bootstrap();await navigate('inbox');break;
 case 'mark-unread':await patchMessage(S.current.id,{is_read:false});toast('已标为未读');break;
 case 'copy-remote-draft':{const m=S.current;await openCompose(null,{data:{account_id:m.account_id,to:m.to_list.map(x=>x.address).join(', '),cc:m.cc_list.map(x=>x.address).join(', '),subject:m.subject,body:m.text_body}});await saveDraft();break;}
 case 'reply':await openCompose(S.current);break;case 'compose':await openCompose();break;
 case 'leave-compose':await saveDraft(false);await navigate('inbox');toast('已保存云端草稿');break;
 case 'save-draft':await saveDraft();break;
 case 'open-draft':{const d=S.drafts.find(d=>d.id===id);let original=null;if(d.data.reply_id)original=(await api('get',{id:d.data.reply_id})).message;await openCompose(original,d);break;}
 case 'delete-draft':await api('draft_delete',{id});await bootstrap();render();toast('草稿已删除');break;
 case 'remove-attachment':composeData();S.compose.attachments.splice(Number(el.dataset.index),1);render();break;
 case 'generate-draft':{const d=composeData();d.keywords=$('#ai-keywords').value;d.aiLanguage=$('#ai-language').value;const r=await api('ai_draft',{reply_id:d.reply_id,keywords:d.keywords,language:d.aiLanguage,subject:d.subject,body:d.body});d.proposal=r.content;render();toast('建议已生成，请确认后填入正文');break;}
 case 'accept-proposal':composeData();S.compose.body=S.compose.proposal+(S.settings.signature?'\n\n'+S.settings.signature:'');S.compose.proposal='';render();toast('已填入正文，请检查后发送');break;
 case 'confirm-send':{const d=composeData();const r=await api('send',{key:d.key,account_id:d.account_id,to:d.to,cc:d.cc,bcc:d.bcc,subject:d.subject,body:d.body,reply_id:d.reply_id,draft_id:d.draftId,attachments:d.attachments});closeModal();S.compose=null;await bootstrap();await navigate('sent');toast(r.warning||'邮件已提交投递',!!r.warning);break;}
 case 'translate':{S.language=$('#translate-language').value;const r=await api('translate',{id:S.current.id,language:S.language});S.translation=r.content;$('#translation-result').textContent=r.content;toast(r.cached?'已读取保存的译文':'译文已生成并保存');break;}
 case 'load-images':renderEmail(true);toast('本次阅读允许加载外部图片');break;
 case 'download-attachment':{const r=await api('attachment',{id:S.current.id,index:Number(el.dataset.index)});download(from64(r.content),r.filename||'附件',r.mime_type);break;}
 case 'reclassify':{ // Explicit request reclassifies just this message, including a previous manual choice.
 const r=await api('classify_one',{id:S.current.id});S.current=(await api('get',{id:S.current.id})).message;await bootstrap();render();toast(r.count?'新分类已保存':'没有匹配的类别');break;}
 case 'reader-contact':{const m=S.current;contactModal(contact(m.from_email)||{email:m.from_email,name:m.from_name});break;}
 case 'find-photo':{toast('正在核对公开姓名与邮箱资料…');const r=await api('contact_photo',{id,retry:el.dataset.retry==='true'});await bootstrap();render();if($('#contact-form'))contactModal(S.contacts.find(c=>c.id===id));toast(r.status==='found'?'匹配照片已保存':r.status==='saved'?'已使用保存的照片':r.status==='busy'?'照片正在查找，请稍后刷新':r.status==='unavailable'?'公开来源暂不可用，已记录；可稍后手动重试':r.status==='insufficient'?'缺少可核对的姓名或机构邮箱，已留空':'没有找到足够匹配的照片，已留空并保存结果');break;}
 case 'find-photos':{toast('正在查找缺失头像，每次处理两位联系人…');const r=await api('contact_photos');await bootstrap();render();toast(`已保存本批查找结果${r.has_more?'，可再次点击继续补全':''}`);break;}
 case 'remove-photo':await api('contact_photo_remove',{id});await bootstrap();render();contactModal(S.contacts.find(c=>c.id===id));toast('照片已移除，已保存留空选择');break;
 case 'add-contact':contactModal();break;case 'edit-contact':contactModal(S.contacts.find(c=>c.id===id));break;
 case 'write-contact':await openCompose();S.compose.to=S.contacts.find(c=>c.id===id).email;render();break;
 case 'filter-contact':await navigate('inbox',{folder:'all',sender:S.contacts.find(c=>c.id===id).email});break;
 case 'export':case 'export-current':exportModal();break;
 case 'change-password':modal('修改账户密码',`<form id="password-form"><p class="muted">这也会修改文献管理系统的登录密码。</p><label>当前密码<input type="password" name="current" required autocomplete="current-password"></label><label>新密码<input type="password" name="next" required minlength="8" autocomplete="new-password"></label><label>再次输入新密码<input type="password" name="confirm" required minlength="8" autocomplete="new-password"></label><div class="form-error"></div><div class="modal-footer"><button class="primary" type="submit">确认修改</button></div></form>`);break;
 case 'logout':if(S.compose)await saveDraft(false);await db.auth.signOut({scope:'local'});S.user=null;S.current=null;S.compose=null;closeModal();loginView();break;
 }}
document.addEventListener('click',async event=>{const el=event.target.closest('[data-action]');if(el){event.preventDefault();event.stopPropagation();if(el.disabled)return;const action=el.dataset.action;el.disabled=true;el.setAttribute('aria-busy','true');try{await handleAction(action,el);}catch(e){error(e);}finally{if(el.isConnected){el.disabled=false;el.removeAttribute('aria-busy');}}return;}if(event.target.closest('input,label,a,select'))return;const row=event.target.closest('[data-open]');if(row)try{await openMail(row.dataset.open);}catch(e){error(e);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')closeModal();if(event.key==='Enter'&&event.target.matches('[data-open]'))openMail(event.target.dataset.open).catch(error);if(event.key==='Tab'&&$('#modal-root .modal')){const nodes=$$('button,input,select,textarea,a[href]',$('#modal-root')).filter(x=>!x.disabled&&x.offsetParent!==null);if(event.shiftKey&&document.activeElement===nodes[0]){nodes.at(-1)?.focus();event.preventDefault();}else if(!event.shiftKey&&document.activeElement===nodes.at(-1)){nodes[0]?.focus();event.preventDefault();}}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='mail-search'){S.query=el.value;S.page=0;clearTimeout(searchTimer);searchTimer=setTimeout(async()=>{const position=el.selectionStart;try{await loadList();const input=$('#mail-search');input?.focus();input?.setSelectionRange(position,position);}catch(e){error(e);}},420);}if(el.id==='contact-search'){S.contactQuery=el.value;const pos=el.selectionStart;render();const n=$('#contact-search');n.focus();n.setSelectionRange(pos,pos);}if(el.closest('#compose-form')&&el.name&&S.compose)S.compose[el.name]=el.value;if(el.id==='ai-keywords'&&S.compose)S.compose.keywords=el.value;});
document.addEventListener('change',async event=>{const el=event.target;try{
 if(el.id==='provider-select')providerFields(el.value,null);
 if(el.id==='category-filter'){S.category=el.value;S.page=0;await loadList();}
 if(el.id==='sender-filter'){S.sender=el.value;S.page=0;await loadList();}
 if(el.id==='contact-group-filter'){S.contactGroup=el.value;render();}
 if(el.id==='reader-category'){await patchMessage(S.current.id,{category_id:el.value||null});toast('手动分类已保存');}
 if(el.id==='select-all'){S.selected=new Set(el.checked?S.messages.map(m=>m.id):[]);render();}
 if(el.matches('.mail-check')){if(el.checked)S.selected.add(el.dataset.id);else S.selected.delete(el.dataset.id);render();}
 if(el.id==='compose-file'){composeData();const files=[...el.files];if(S.compose.attachments.length+files.length>10)throw Error('最多10个附件');const total=files.reduce((s,f)=>s+f.size,0)+S.compose.attachments.reduce((s,x)=>s+x.size,0);if(total>12000000)throw Error('附件总大小最大12MB');for(const f of files)S.compose.attachments.push({filename:f.name,mime_type:f.type,size:f.size,content:await to64(f)});render();}
 }catch(e){error(e);}});
document.addEventListener('submit',async event=>{event.preventDefault();const f=event.target;const formId=f.getAttribute('id');const button=$('button[type=submit]',f);const buttonHTML=button?.innerHTML;if(button?.disabled)return;if(button){button.disabled=true;button.textContent=formId==='account-form'?'正在保存…':'正在处理…';}const err=$('.form-error',f);if(err)err.textContent='';try{const data=Object.fromEntries(new FormData(f));
 if(formId==='auth-form'){S.authBusy=true;if(authMode==='login')await login(data.identifier,data.password,!!data.remember);else await register(data.username,data.email,data.password,!!data.remember);await start();}
 if(formId==='account-form'){const service=$('#provider-select').value;data.provider=service==='gmail'?'gmail':service==='outlook'?'outlook':'imap';if(service==='qq'){data.imap_host='imap.qq.com';data.smtp_host='smtp.qq.com';}const r=await api('account_save',data);closeModal();await bootstrap();await navigate('settings');toast('邮箱连接已保存');if(data.password){await api('account_test',{id:r.id});toast('连接验证通过，正在同步');await syncAll();}else if(data.client_id){const auth=await api('oauth_start',{id:r.id});window.location.assign(auth.url);}}
 if(formId==='category-form'){await api('category_save',data);closeModal();await bootstrap();render();toast('邮件类别已保存，正在按新类别更新 AI 分类…');try{const r=await classifyPending();await bootstrap();if(listViews.includes(S.view))await loadList(false);render();toast(r.busy?'新类别已保存，后台正在更新分类':`新类别已保存，更新了 ${r.count} 封邮件`);}catch(e){toast('类别已保存；AI 更新未完成：'+e.message,true);}}
 if(formId==='preferences-form'){await api('settings_save',{auto_classify:!!data.auto_classify,auto_contact_photos:!!data.auto_contact_photos,translation_language:data.translation_language,contact_groups:data.contact_groups.split(/[,，]/).map(x=>x.trim()).filter(Boolean),signature:data.signature});await bootstrap();render();toast('偏好已保存');}
 if(formId==='contact-form'){const photo=f.elements.photo_file.files[0];delete data.photo_file;if(photo){if(photo.size>2000000)throw Error('照片最大2MB');data.photo=await to64(photo);data.photo_type=photo.type;}await api('contact_save',data);closeModal();await bootstrap();render();toast('联系人资料已保存');}
 if(formId==='bulk-category-form'){closeModal();await bulkPatch({category_id:data.category_id||null});}
 if(formId==='compose-form'){const d=composeData();modal('确认发送邮件',`<div class="send-summary"><p><span>发件邮箱</span><strong>${esc(account(d.account_id)?.email)}</strong></p><p><span>收件人</span><strong>${esc(d.to)}</strong></p>${d.cc?'<p><span>抄送</span>'+esc(d.cc)+'</p>':''}${d.bcc?'<p><span>密送</span>'+esc(d.bcc)+'</p>':''}<p><span>主题</span><strong>${esc(d.subject)}</strong></p><div class="send-preview">${esc(d.body)}</div>${d.attachments.length?'<p>'+d.attachments.length+' 个附件</p>':''}</div><div class="modal-footer"><button class="secondary" data-action="close-modal">继续编辑</button><button class="primary" data-action="confirm-send">${I('send',16)} 确认发送</button></div>`);}
 if(formId==='export-form')await doExport(f);
 if(formId==='password-form'){if(data.next!==data.confirm)throw Error('两次新密码不一致');const auth=await db.auth.signInWithPassword({email:S.user.email,password:data.current});if(auth.error)throw Error('当前密码不正确');const {error:e}=await db.auth.updateUser({password:data.next});if(e)throw e;closeModal();toast('密码已更新');}
 }catch(e){if(err?.isConnected)err.textContent=e.message;else error(e);}finally{S.authBusy=false;if(button?.isConnected){button.disabled=false;button.innerHTML=buttonHTML;}}});
window.addEventListener('beforeunload',event=>{if(S.view==='compose'&&S.compose&&(S.compose.body.trim()||S.compose.to.trim())){event.preventDefault();event.returnValue='';}});
async function start(){const {data:{session}}=await db.auth.getSession();if(!session){S.user=null;loginView();return;}if(S.loading)return;S.loading=true;try{S.user=session.user;await bootstrap();S.view=location.hash.startsWith('#settings')?'settings':'inbox';S.folder='inbox';S.account='';await loadList(false);render();if(location.hash.includes('oauth=success'))toast('邮箱授权成功，可以开始同步');if(location.hash.includes('oauth=error'))toast('授权未完成，请检查OAuth应用配置后重试',true);clearInterval(interval);interval=setInterval(()=>syncAll(false,true).catch(()=>{}),60000);if(S.accounts.some(a=>a.enabled&&(!a.last_sync||Date.now()-Date.parse(a.last_sync)>60000)))syncAll(false,true).catch(()=>{});}catch(e){error(e);$('#view-content')?null:loginView();}finally{S.loading=false;}}
db.auth.onAuthStateChange((event,session)=>{if(booting)return;if(event==='SIGNED_OUT'&&!S.authBusy){S.user=null;loginView();}else if(event==='SIGNED_IN'&&session?.user.id!==S.user?.id)setTimeout(()=>start().catch(error),0);});
await start();booting=false;
